namespace r=c::room_objects;
unsigned checks{},rooms{},installed{},objects{},classifications{};float maximum_error{};
std::vector<std::uint8_t> memory(0x800000);
void check(bool value,const char* why){++checks;if(!value){std::fprintf(stderr,"room-object check %u failed: %s\n",checks,why);std::exit(1);}}
R5900Context context(std::uint32_t pc){R5900Context ctx;ctx.pc=pc;ctx.g[29].lo=0x7f0000;ctx.g[31].lo=0x1234;return ctx;}
std::uint32_t invoke(std::uint32_t pc,std::uint32_t a0=0,std::uint32_t a1=0,std::uint32_t a2=0){auto ctx=context(pc);ctx.g[4].lo=a0;ctx.g[5].lo=a1;ctx.g[6].lo=a2;PS2Runtime runtime;runtime.lookupFunction(pc)(memory.data(),&ctx,&runtime);return std::uint32_t(ctx.g[2].lo);}
std::vector<std::byte> load(const char* path){std::ifstream file(path,std::ios::binary);const std::vector<char> raw{std::istreambuf_iterator<char>(file),{}};check(!raw.empty(),"owned room-object fixture");const auto bytes=std::as_bytes(std::span(raw));return{bytes.begin(),bytes.end()};}
void vector_equal(c::Vec3 a,c::Vec3 b,const char* why){for(const auto pair:{std::pair{a.x,b.x},std::pair{a.y,b.y},std::pair{a.z,b.z}}){const auto error=std::abs(pair.first-pair.second);maximum_error=std::max(maximum_error,error);check(error<=0.0001f,why);}}
void room(const char* type_path,const char* sto_path,std::uint16_t room,const char* grid_path){
    const auto types=load(type_path),sto=load(sto_path),grid=load(grid_path);auto native=r::Owner::import(types,sto);invoke(0x6acf80);const auto type_count=ref_read<std::uint32_t>(reinterpret_cast<const std::uint8_t*>(types.data()),4);const auto type_offset=ref_read<std::uint32_t>(reinterpret_cast<const std::uint8_t*>(types.data()),8),model_offset=ref_read<std::uint32_t>(reinterpret_cast<const std::uint8_t*>(types.data()),12);
    if(type_offset)std::memcpy(memory.data()+0x74b1c0,types.data()+type_offset,8*type_count);
    if(model_offset)std::memcpy(memory.data()+0x74b180,types.data()+model_offset,2*type_count);
    const auto count=ref_read<std::int32_t>(reinterpret_cast<const std::uint8_t*>(sto.data()),4);for(std::int32_t i=0;i<count;++i){std::memcpy(memory.data()+0x1000,sto.data()+8+16*std::size_t(i),16);check(invoke(0x6ad0f0,0x1000)!=0,"owned placement original allocation admitted");}
    const auto ids=native.objects();check(ids.size()==unsigned(count),"stock native/original placement count");for(unsigned i=0;i<ids.size();++i){const auto* object=native.get(ids[i]);const auto at=0x3c4580+60*(i+1);check(object&&object->active==bool(memory[at])&&object->room==memory[at+1]&&object->external_id==memory[at+2],"original physical slot/external ID/room distinction");check(object->type==ref_read<std::uint16_t>(memory.data(),at+4)&&object->rotation==ref_read<std::uint16_t>(memory.data(),at+0x14),"original placement type/rotation");check(object->x==std::int8_t(memory[at+0x18])&&object->z==std::int8_t(memory[at+0x19])&&object->initial_x==std::int8_t(memory[at+0x16])&&object->initial_z==std::int8_t(memory[at+0x17]),"original signed current/initial cells");check(object->allowed_directions==memory[at+0x1a]&&object->parameter==memory[at+0x22],"original direction/parameter defaults");check(object->width==std::int8_t(memory[at+0x1f])&&object->height==std::int8_t(memory[at+0x20])&&object->depth==std::int8_t(memory[at+0x21]),"original profile/explicit dimensions and zero-capacity height");check(object->control_flags==ref_read<std::uint32_t>(memory.data(),at+0x24),"original imported control flags");++objects;}
    ref_write(memory.data(),0x3243dc,room);std::memcpy(memory.data()+0x20000,grid.data(),grid.size());invoke(0x6ad860,0x20000);const auto admitted=native.install_grid(room,grid);check(admitted==bool(memory[0x745d68]),"original active-room grid installation admission");++rooms;if(!admitted)return;++installed;
    const auto* g=native.grid();check(g&&g->width==ref_read<std::int16_t>(memory.data(),0x3c4d0c)&&g->depth==ref_read<std::int16_t>(memory.data(),0x3c4d0e),"original signed grid dimensions");vector_equal(g->origin,ref_read<c::Vec3>(memory.data(),0x3c4d00),"original room grid origin");
    for(unsigned layer=0;layer<4;++layer)for(unsigned i=0;i<g->base.size();++i)check(native.layers()[layer][i]==ref_read<std::uint32_t>(memory.data(),0x7461f0+layer*0x480+4*i),"original four occupancy height layers");
    for(unsigned i=0;i<8;++i){const auto mapped=native.mapped(i);const auto original=std::int8_t(memory[0x3c5613+4*i]);check(bool(mapped)==(original>=0),"original eight cached-cell presence");if(mapped)check(native.get(*mapped)->external_id==memory[0x3c4582+60*unsigned(original)],"original cached-cell native owner mapping");}
    for(unsigned i=0;i<ids.size();++i){const auto* object=native.get(ids[i]);invoke(0x6ad360,0x1000,0x3c4580+60*(i+1));vector_equal(native.center(*object),ref_read<c::Vec3>(memory.data(),0x1000),"original typed object center/rotated footprint");}
    for(int x=0;x<g->width;++x)for(int z=0;z<g->depth;++z){const auto found=native.at_cell(x,z);const auto original=std::int8_t(invoke(0x6afbd0,std::uint32_t(x),std::uint32_t(z)));check(bool(found)==(original>=0),"original enabled/current-room/rotated footprint cell admission");if(found)check(native.get(*found)->external_id==memory[0x3c4582+60*unsigned(original)],"original first containing room object");}
    for(unsigned i=0;i<300;++i){const c::Vec3 p{g->origin.x+float((i*17)%unsigned(g->width))*50+float(i%3)*0.25f,g->origin.y+float((i%4)*100),g->origin.z+float((i*11)%unsigned(g->depth))*50+float(i%5)*0.25f};ref_write(memory.data(),0x1000,p);memory[0x745d58]=i%2;const auto value=native.classify(p,i%2);const auto original=invoke(0x6b0890,0x1100,0x1000);check(unsigned(value.status)==original,"original height-band/object/mask classification");check(value.cell.x==ref_read<std::int32_t>(memory.data(),0x1100)&&value.cell.z==ref_read<std::int32_t>(memory.data(),0x1104),"original float conversion before cell admission");const auto refined=native.refine(p,i%2,{});check(unsigned(refined.status)==invoke(0x6b0ac0,0x1100,0x1000,255),"original refined capacity with absent exclusion");++classifications;}
    auto foreign=r::Owner::import(types,sto);check(!ids.empty()&&!foreign.get(ids[0]),"foreign native object domain refused");
    for(unsigned i=0;i<8;++i){const auto m=native.mapped(i);const auto* object=m?native.get(*m):nullptr;check(native.mapped_presence(i,true)==bool(object),"C3nonzero requires cached mapping");check(native.mapped_presence(i,false)==(!object||bool(object->control_flags&2)),"C3zero admits missing or transitioning object");if(object){check(native.mapped_external(i,std::int8_t(object->external_id))==!(object->control_flags&2),"C2external identity and transition bit");}}
    if(!ids.empty()){
        const auto first_id=ids[0];const auto external=native.get(first_id)->external_id;const auto previous=*native.get(first_id);check(!native.move_external(255,0,0)&&!native.change_external_flags(255,16,0),"VM unsigned external-ID bound preserves all objects");
        check(native.change_external_flags(external,16,0)&&bool(native.get(first_id)->control_flags&16),"VM first active external flag set");check(native.change_external_flags(external,32,16)&&!(native.get(first_id)->control_flags&16)&&bool(native.get(first_id)->control_flags&32),"VM external flag clear/set ordering");
        check(!native.move_external(external,255,255),"VM unsigned cell bounds reject outside grid");if(g->width>1&&g->depth>1){check(native.move_external(external,1,1),"VM active external coordinate update");check(native.get(first_id)->x==1&&native.get(first_id)->z==1,"VM stores signed cell bytes after unsigned admission");vector_equal(native.get(first_id)->center,native.center(*native.get(first_id)),"VM coordinate update publishes native center");}
        if(external==0)check(!native.enable_external(0,false),"nonactive slot0 shadows external0 only in original enable lookup");
        check(native.get(first_id)->room==previous.room&&native.get(first_id)->type==previous.type,"VM mutations preserve native object ownership/type");
    }
    auto explicit_sto=sto;auto* bytes=reinterpret_cast<std::uint8_t*>(explicit_sto.data());const auto flags=ref_read<std::uint32_t>(bytes,20)|4;ref_write(bytes,20,flags);bytes[15]=3;bytes[16]=2;bytes[17]=4;auto explicit_native=r::Owner::import(types,explicit_sto);invoke(0x6acf80);std::memcpy(memory.data()+0x1000,explicit_sto.data()+8,16);const auto explicit_original=invoke(0x6ad0f0,0x1000);const auto explicit_id=explicit_native.objects().front();const auto* object=explicit_native.get(explicit_id);check(object->type==31&&ref_read<std::uint16_t>(memory.data(),explicit_original+4)==31,"explicit placement selects reserved native type31");check(object->width==3&&object->depth==4&&object->height==7&&std::int8_t(memory[explicit_original+0x1f])==3&&std::int8_t(memory[explicit_original+0x20])==7&&std::int8_t(memory[explicit_original+0x21])==4,"explicit dimensions and zero-capacity height match original");
}
int main(int argc,char** argv){check(argc==3,"room-object manifest/profile arguments");const auto profiles=load(argv[2]);check(profiles.size()==200,"owned ten footprint profiles");std::memcpy(memory.data()+0x723740,profiles.data(),profiles.size());for(unsigned i=0;i<4;++i)memory[0x719900+i]=std::uint8_t(i*2);std::ifstream manifest(argv[1]);std::string line;while(std::getline(manifest,line)){std::istringstream fields(line);std::string types,sto,number,grid;std::getline(fields,types,'\t');std::getline(fields,sto,'\t');std::getline(fields,number,'\t');std::getline(fields,grid);if(!types.empty())room(types.c_str(),sto.c_str(),std::uint16_t(std::stoi(number)),grid.c_str());}check(rooms>0&&installed>0,"actual room-object resource coverage");std::printf("{\"checks\":%u,\"maximum_error\":%.9g,\"rooms\":%u,\"installed\":%u,\"placements\":%u,\"classifications\":%u,\"game_launched\":false}\n",checks,double(maximum_error),rooms,installed,objects,classifications);}
